function _setAccuracy(accurate){
  document.getElementById('rv-accuracy').value=accurate?'yes':'no';
  var yes=document.getElementById('acc-yes'),no=document.getElementById('acc-no');
  if(!yes||!no)return;
  yes.style.background=accurate?'var(--gnl)':'var(--bg3)';yes.style.color=accurate?'var(--gn)':'var(--t2)';yes.style.borderColor=accurate?'var(--gn)':'var(--bd)';
  no.style.background=!accurate?'var(--rdl)':'var(--bg3)';no.style.color=!accurate?'var(--rd)':'var(--t2)';no.style.borderColor=!accurate?'var(--rd)':'var(--bd)';
}
function _setStars(n){
  document.getElementById('rv-rating').value=n;
  var labels=['','별로예요','아쉬워요','보통이에요','좋아요','아주 좋아요'];
  var lbl=document.getElementById('rv-star-label');if(lbl)lbl.textContent=labels[n]||'';
  document.querySelectorAll('#rv-stars .star').forEach(function(s,i){s.classList.toggle('on',i<n);});
}
function _hoverStar(n){document.querySelectorAll('#rv-stars .star').forEach(function(s,i){s.style.color=i<n?'var(--br)':'var(--bd)';});}
function _leaveStar(){
  var n=parseInt((document.getElementById('rv-rating')||{}).value)||0;
  document.querySelectorAll('#rv-stars .star').forEach(function(s,i){s.style.color=i<n?'var(--br)':'var(--bd)';});
}

function _toggleCriteria(btn){
  btn.classList.toggle('on');
  var on=btn.classList.contains('on');
  btn.style.borderColor=on?'var(--br)':'var(--bd)';
  btn.style.background=on?'var(--brl)':'var(--bg3)';
  btn.style.color=on?'var(--br)':'var(--t2)';
}

function _submitReview(targetId,targetName,targetType,applyId){
  var rating=parseInt((document.getElementById('rv-rating')||{}).value)||0;
  if(!rating){_yToast('별점을 선택해주세요');return;}
  var comment=(document.getElementById('rv-comment')||{}).value||'';
  var criteria=[];
  document.querySelectorAll('#rv-criteria .on').forEach(function(b){criteria.push(b.dataset.c);});
  var accuracyVal=(document.getElementById('rv-accuracy')||{}).value||'';
  var postAccurate=accuracyVal==='yes'?true:accuracyVal==='no'?false:null;
  var btn=document.getElementById('rv-submit');btn.textContent='제출 중...';btn.disabled=true;

  _db.collection('yongcha_reviews').add({
    reviewerId:_CU.uid,reviewerName:_CU.name,reviewerType:_CU.type,
    revieweeId:targetId,revieweeName:targetName,revieweeType:targetType,
    applyId:applyId,rating:rating,criteria:criteria,comment:comment,
    postAccurate:postAccurate,isFake:postAccurate===false,
    createdAt:firebase.firestore.FieldValue.serverTimestamp()
  }).then(function(){
    _calcTrustScore(targetId);
    _yToast('평가가 등록됐어요!');
    _closeModal();
    if(applyId){
      var updateField=_CU.type==='agency'?{agencyReviewed:true}:{driverReviewed:true};
      _db.collection('yongcha_applies').doc(applyId).update(updateField).catch(function(){});
    }
  }).catch(function(e){btn.textContent='평가 제출하기';btn.disabled=false;_yToast('오류: '+e.message);});
}

function _driverGrade(score, completedRoutes){
  var s=score||0, r=completedRoutes||0;
  if(s>=91&&r>=30)return{label:'👑 VIP',color:'var(--br)',bg:'var(--brl)',short:'VIP'};
  if(s>=71&&r>=10)return{label:'우수',color:'var(--ac)',bg:'var(--acl)',short:'우수'};
  if(s>=41||r>=3)return{label:'일반',color:'var(--t2)',bg:'var(--bg3)',short:'일반'};
  return{label:'🌱 새내기',color:'var(--t3)',bg:'var(--bg3)',short:'새내기'};
}

function _calcTrustScore(userId){
  _db.collection('yongcha_reviews').where('revieweeId','==',userId).get().then(function(snap){
    if(snap.empty)return;
    var total=0,count=0,fakeCount=0,lastFakeAt=null,highRatingCount=0;
    snap.forEach(function(doc){
      var d=doc.data();
      total+=d.rating||0;count++;
      if(d.isFake){
        fakeCount++;
        var ct=d.createdAt;
        if(ct&&(!lastFakeAt||(ct.seconds||0)>(lastFakeAt.seconds||0)))lastFakeAt=ct;
      }
      if((d.rating||0)>=4.5)highRatingCount++;
    });
    var avg=count>0?Math.round((total/count)*10)/10:0;
    var upd={rating:avg,reviewCount:count,fakeCount:fakeCount};
    if(lastFakeAt)upd.lastFakeAt=lastFakeAt;
    if(fakeCount>=10)upd.postSuspended=true;
    else if(fakeCount>=5)upd.postRestrictedAt=lastFakeAt||firebase.firestore.FieldValue.serverTimestamp();
    // 기사 트러스트 포인트 갱신 (완료건수는 별도 관리)
    _db.collection('yongcha_users').doc(userId).get().then(function(us){
      if(!us.exists)return;
      var ud=us.data();
      if(ud.type==='driver'){
        var completed=ud.completedRoutes||0;
        var score=Math.min(100, completed*5 + highRatingCount*10);
        upd.trustScore=score;
      }
      _db.collection('yongcha_users').doc(userId).update(upd).catch(function(){});
    }).catch(function(){
      _db.collection('yongcha_users').doc(userId).update(upd).catch(function(){});
    });
  }).catch(function(){});
}

