// ── FCM 알림 ─────────────────────────────────────────────────
/* FCM 초기화.
   과거 실패 원인 3가지 — 전부 여기와 서버에서 고쳤다.
     1) yongcha.app 이 모든 경로를 yongcha.html 로 응답해 /firebase-messaging-sw.js 가
        text/html 로 내려왔다 → SW 등록이 MIME 오류로 거부됨. (_worker.js handleYongcha 에서 수정)
     2) getToken() 을 vapidKey / serviceWorkerRegistration 없이 호출했다 → 토큰 발급 실패.
     3) yongcha_fcm_tokens 컬렉션에 Firestore 규칙이 없어 쓰기가 permission-denied 였다.
        (firestore.rules 에 규칙 추가) */
var _Y_VAPID='BHO3mU6K2VlLkYfUgsunV5zXsx6oOc_I4dIyE9ErYPBZE5AkBhPP-HUmQhqvHLDsbjcRgEDsMbXg0TYiSiKW93c';
var _yFcmReg=null;

function _yInitFCM(){
  if(!('serviceWorker' in navigator)){console.warn('[FCM] ServiceWorker 미지원 브라우저');return;}
  if(!firebase.messaging||!firebase.messaging.isSupported||!firebase.messaging.isSupported()){
    console.warn('[FCM] 이 브라우저는 FCM 미지원 (iOS Safari는 홈화면 추가 후 가능)');return;
  }
  if(typeof Notification==='undefined'||Notification.permission==='denied')return;

  var msg;
  try{ msg=firebase.messaging(); }catch(e){ console.warn('[FCM] 초기화 실패:',e); return; }

  // 포그라운드 수신은 권한과 무관하게 먼저 연결
  try{
    msg.onMessage(function(payload){
      var n=(payload||{}).notification||{};
      _yToast(' '+(n.title||'알림')+(n.body?' — '+n.body:''));
      var dot=document.getElementById('notif-dot');
      if(dot)dot.style.display='block';
    });
  }catch(e){}

  navigator.serviceWorker.register('/firebase-messaging-sw.js',{scope:'/'})
  .then(function(reg){
    _yFcmReg=reg;
    return navigator.serviceWorker.ready.then(function(){return reg;});
  })
  .then(function(reg){
    return Notification.requestPermission().then(function(perm){
      if(perm!=='granted'){console.info('[FCM] 알림 권한 거부됨');return null;}
      return msg.getToken({vapidKey:_Y_VAPID,serviceWorkerRegistration:reg});
    });
  })
  .then(function(token){
    if(!token)return;
    return _db.collection('yongcha_fcm_tokens').doc(_CU.uid).set({
      token:token,userId:_CU.uid,
      type:_CU.type,region:_CU.region||'',
      updatedAt:firebase.firestore.FieldValue.serverTimestamp()
    });
  })
  .then(function(){ if(_yFcmReg)console.info('[FCM] 준비 완료'); })
  .catch(function(e){
    // 등록 실패해도 앱 기능은 그대로 — 조용히 실패하지 말고 원인은 남긴다
    console.warn('[FCM] 등록/토큰 실패:',(e&&(e.code||e.message))||e);
  });
}

function _yNotify(recipientId,title,body,type){
  if(!recipientId||!title)return;
  _db.collection('yongcha_notifications').add({
    userId:recipientId,title:title,body:body||'',
    type:type||'system',
    read:false,createdAt:firebase.firestore.FieldValue.serverTimestamp()
  }).catch(function(){});
  // FCM push
  _yGetToken().then(function(tok){
    return _db.collection('yongcha_fcm_tokens').doc(recipientId).get()
      .then(function(snap){
        if(!snap.exists)return;
        var token=snap.data().token;
        if(!token)return;
        return fetch('/api/ctrl-notify',{
          method:'POST',
          headers:{'Content-Type':'application/json','Authorization':'Bearer '+tok},
          body:JSON.stringify({token:token,title:title,body:body||''})
        });
      });
  }).catch(function(){});
}

function _yStartNotifListener(){
  if(_notifUnsub){_notifUnsub();_notifUnsub=null;}
  _notifUnsub=_db.collection('yongcha_notifications')
    .where('userId','==',_CU.uid).where('read','==',false)
    .onSnapshot(function(snap){
      var dot=document.getElementById('notif-dot');
      if(dot)dot.style.display=snap.size>0?'block':'none';
    },function(){});
}

